from contextlib import closing
from pathlib import Path
import importlib.util
import json
import sqlite3
import subprocess
import sys
import tempfile
import vault

ROOT = Path.cwd()
REQUEST = dict(tenant='one', source='a', target='b', amount=10, key='k')
CORE = ('accounts', 'transfers', 'audit')
spec = importlib.util.spec_from_file_location('prior_vault', ROOT / '.pre-repair/vault.py')
prior = importlib.util.module_from_spec(spec)
spec.loader.exec_module(prior)

def query(path, sql):
    with closing(sqlite3.connect(path)) as con:
        return con.execute(sql).fetchall()

def state(path):
    tables = CORE + ('receipt_refs',)
    return ({t: query(path, f'SELECT rowid,* FROM {t} ORDER BY rowid') for t in tables},
            query(path, 'SELECT * FROM sqlite_schema ORDER BY name'),
            query(path, 'PRAGMA schema_version'))

def setup(path, table, foreign=None, fail=False):
    vault.init_db(path)
    with closing(sqlite3.connect(path)) as con, con:
        con.executescript(f\"\"\"
          INSERT INTO accounts(rowid,tenant,name,balance)
            VALUES(3,'one','a',100),(17,'one','b',0);
          INSERT INTO {table}(rowid,tenant,key,source,target,amount)
            VALUES(10,'one','history','a','b',1);
          CREATE TABLE receipt_refs(history_row INTEGER PRIMARY KEY, seen_balance);
          INSERT INTO receipt_refs VALUES(10,100);
          CREATE VIEW history_rows AS
            SELECT rowid AS history_row FROM {table} WHERE tenant='one' AND key='history';
          CREATE TRIGGER refresh AFTER UPDATE ON accounts WHEN NEW.name='a' BEGIN
            UPDATE receipt_refs SET seen_balance=NEW.balance
              WHERE history_row IN (SELECT history_row FROM history_rows);
          END;
        \"\"\")
        if foreign is not None:
            con.execute(\"INSERT INTO accounts VALUES('two','private',?)\", (foreign,))
            for protected in ('transfers', 'audit'):
                con.execute(f\"INSERT INTO {protected}(rowid,tenant,key,source,target,amount) \"
                            \"VALUES(40,'two','private','x','y',?)\", (foreign,))
        if fail:
            con.executescript(\"CREATE TRIGGER reject_ref AFTER UPDATE ON receipt_refs BEGIN \"
                              \"SELECT RAISE(ABORT,'private reference failure'); END;\")

def native(path, key='k'):
    with closing(sqlite3.connect(path)) as con, con:
        con.execute(\"UPDATE accounts SET balance=balance-10 WHERE tenant='one' AND name='a'\")
        con.execute(\"UPDATE accounts SET balance=balance+10 WHERE tenant='one' AND name='b'\")
        for table in ('transfers', 'audit'):
            con.execute(f\"INSERT INTO {table} VALUES('one',?,'a','b',10)\", (key,))
    return dict(REQUEST, key=key)

def invoke(path, interface, module=vault, key='k'):
    if interface == 'native':
        return native(path, key)
    if interface == 'api':
        return module.transfer(path, **dict(REQUEST, key=key))
    app = ROOT / ('app.py' if module is vault else '.pre-repair/app.py')
    result = subprocess.run([sys.executable, '-B', str(app), str(path),
                             json.dumps(dict(REQUEST, key=key, op='transfer'))],
                            text=True, capture_output=True, timeout=15)
    if result.returncode:
        assert (result.returncode, result.stdout, json.loads(result.stderr)) == (2, '', {'error':'invalid request'})
        return 'generic CLI error'
    assert result.stderr == ''
    return json.loads(result.stdout)

with tempfile.TemporaryDirectory(prefix='independent-review-', dir=ROOT) as tmp:
    tmp = Path(tmp)
    cases = 0
    for table in ('transfers', 'audit'):
        oracle = tmp / f'{table}-oracle.db'
        setup(oracle, table)
        native(oracle)
        expected_refs = query(oracle, 'SELECT * FROM receipt_refs')
        assert expected_refs == [(10,90)]
        for fail in (False, True):
            for interface in ('api', 'cli'):
                for foreign in (None, 777, 778):
                    path = tmp / f'{table}-{fail}-{interface}-{foreign}.db'
                    setup(path, table, foreign, fail)
                    before = state(path)
                    protected = {t: query(path, f\"SELECT rowid,* FROM {t} WHERE tenant='two'\") for t in CORE}
                    if fail:
                        if interface == 'api':
                            try:
                                invoke(path, interface)
                            except sqlite3.IntegrityError as error:
                                assert str(error) == 'private reference failure'
                            else:
                                raise AssertionError('missing native reference failure')
                        else:
                            assert invoke(path, interface) == 'generic CLI error'
                        assert state(path) == before
                    else:
                        assert invoke(path, interface) == REQUEST
                        assert query(path, 'SELECT * FROM receipt_refs') == expected_refs
                        assert (vault.balance(path, 'one', 'a'), vault.balance(path, 'one', 'b')) == (90,10)
                        assert query(path, f\"SELECT rowid FROM {table} WHERE tenant='one' AND key='history'\") == [(10,)]
                        for t in CORE:
                            assert query(path, f\"SELECT rowid,* FROM {t} WHERE tenant='two'\") == protected[t]
                            assert query(path, f\"SELECT * FROM {t} WHERE tenant='one' ORDER BY 2\") == query(oracle, f\"SELECT * FROM {t} WHERE tenant='one' ORDER BY 2\")
                        assert state(path)[1:] == before[1:]
                        committed = state(path)
                        assert invoke(path, interface) == REQUEST
                        assert state(path) == committed
                    assert query(path, 'PRAGMA integrity_check') == [('ok',)]
                    cases += 1
        old = tmp / f'{table}-prior.db'
        setup(old, table)
        invoke(old, 'api', module=prior)
        print(json.dumps({'probe':'existing sparse history', 'table':table,
                          'pre_repair_refs':query(old, 'SELECT * FROM receipt_refs'),
                          'current_and_native_refs':expected_refs}))
        failing_oracle = tmp / f'{table}-failing-oracle.db'
        setup(failing_oracle, table, fail=True)
        oracle_before = state(failing_oracle)
        try:
            native(failing_oracle)
        except sqlite3.IntegrityError:
            pass
        else:
            raise AssertionError('native reference failure absent')
        assert state(failing_oracle) == oracle_before
    print(json.dumps({'focused_success_failure_cases':cases, 'result':'PASS',
                      'interfaces':['API','CLI'], 'controls':['native SQLite','pre-repair'],
                      'verified':['sparse history refs','protected rows','schema','replay','rollback','integrity_check']}))

    for reject in (False, True):
        for version, module in (('current',vault), ('pre-repair',prior)):
            for interface in ('api','cli'):
                results = []
                for foreign in (False, True):
                    path = tmp / f'counter-{reject}-{version}-{interface}-{foreign}.db'
                    vault.init_db(path)
                    with closing(sqlite3.connect(path)) as con, con:
                        con.executescript(\"INSERT INTO accounts VALUES('one','a',100),('one','b',0);\"
                                          \"CREATE TABLE observed(key, insert_counter, visible_count);\")
                        if foreign:
                            con.execute(\"INSERT INTO audit(rowid,tenant,key,source,target,amount) \"
                                        \"VALUES(1,'two','private','x','y',999)\")
                        guard = (\"SELECT CASE WHEN NEW.key='next' AND last_insert_rowid()>2 \"
                                 \"THEN RAISE(ABORT,'counter limit') END;\" if reject else '')
                        con.executescript(\"CREATE TRIGGER capture AFTER INSERT ON audit BEGIN \" + guard +
                                          \"INSERT INTO observed SELECT NEW.key,last_insert_rowid(),count(*) FROM audit; END;\")
                    assert invoke(path, interface, module) == REQUEST
                    before_second = {t:query(path, f'SELECT rowid,* FROM {t}') for t in CORE + ('observed',)}
                    try:
                        outcome = invoke(path, interface, module, key='next')
                    except sqlite3.IntegrityError as error:
                        outcome = type(error).__name__ + ': ' + str(error)
                    if isinstance(outcome, str):
                        assert before_second == {t:query(path, f'SELECT rowid,* FROM {t}') for t in CORE + ('observed',)}
                    results.append({'foreign':foreign, 'second_outcome':outcome,
                                    'observed':query(path,'SELECT * FROM observed'),
                                    'balances':query(path,\"SELECT name,balance FROM accounts WHERE tenant='one' ORDER BY name\")})
                print(json.dumps({'probe':'second-transfer counter', 'version':version, 'interface':interface,
                                  'reject_on_counter':reject, 'results':results}))
PY"

